+	offset = gluster_rpc4_0_dissect_dict(tree, pinfo, tvb, hf_glusterfs_dict, offset);
+	offset = glusterfs_rpc_dissect_gf_proto_lease(tree, tvb, offset);
+
+	return offset;
+}
